    """Shift all non-background cells down by one row, dropping the bottom row."""
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    h, w = len(grid), len(grid[0])
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
